    "version": "v0.9"
  },
  {
    "updateComponents": {
      "surfaceId": "kyoto_itinerary_surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header",
            "summary",
            "assumptions_title",
            "assumptions_text",
            "day1_card",
            "day2_card",
            "day3_card",
            "actions_title",
            "actions_row",
            "sources_title",
            "sources_row"
          ]
        },
        {
          "id": "header",
          "component": "Text",
          "text": "3-Day Family Itinerary for Kyoto",
          "variant": "h2"
        },
        {
          "id": "summary",
          "component": "Text",
          "text": "This 3-day family itinerary for Kyoto focuses on high-impact historical sites, manageable outdoor activities, and engaging food experiences suitable for children ages 8 and 10. The plan utilizes Kyoto's subway and bus systems to minimize walking between transit stops, ensuring no leg exceeds the 30-minute walking limit. April 5-7 falls within the peak cherry blossom (sakura) season, so early starts are recommended to avoid maximum congestion."
        },
        {
          "id": "assumptions_title",
          "component": "Text",
          "text": "Assumptions",
          "variant": "h3"
        },
        {
          "id": "assumptions_text",
          "component": "Text",
          "text": "Travelers are staying centrally near Kyoto Station or Gion/Kawaramachi to maximize transit connectivity. The family is utilizing IC cards (ICOCA or Suica) for seamless public transport payments."
        },
        {
          "id": "day1_card",
          "component": "Card",
          "child": "day1_col"
        },
        {
          "id": "day1_col",
          "component": "Column",
          "children": [
            "day1_header_row",
            "day1_subtitle",
            "day1_desc",
            "day1_btn"
          ]
        },
        {
          "id": "day1_header_row",
          "component": "Row",
          "children": [
            "day1_icon",
            "day1_title"
          ],
          "align": "center"
        },
        {
          "id": "day1_icon",
          "component": "Image",
          "url": "../assets/r_000784_01_1_bell.svg",
          "variant": "icon"
        },
        {
          "id": "day1_title",
          "component": "Text",
          "text": "Day 1 - The Thousand Gates & Ancient Stages",
          "variant": "h3"
        },
        {
          "id": "day1_subtitle",
          "component": "Text",
          "text": "Southern Higashiyama Course | Fushimi Inari & Kiyomizu-dera | Iconic History",
          "variant": "h4"
        },
        {
          "id": "day1_desc",
          "component": "Text",
          "text": "Start the morning at Fushimi Inari Taisha (JR Nara Line to Inari Station, located immediately outside). The hike through the torii gates is adjustable; turn back at the Yotsutsuji intersection for a manageable 45-minute round trip. In the afternoon, take the Keihan Line to Kiyomizu-Gojo and a short taxi or bus ride to Kiyomizu-dera. The temple's wooden stage offers great views, and the approach (Ninenzaka) is filled with kid-friendly souvenir shops."
        },
        {
          "id": "day1_btn",
          "component": "Button",
          "child": "day1_btn_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.japan-guide.com/e/e3915.html"
              }
            }
          }
        },
        {
          "id": "day1_btn_text",
          "component": "Text",
          "text": "Fushimi Inari Guide"
        },
        {
          "id": "day2_card",
          "component": "Card",
          "child": "day2_col"
        },
        {
          "id": "day2_col",
          "component": "Column",
          "children": [
            "day2_header_row",
            "day2_subtitle",
            "day2_desc",
            "day2_btn"
          ]
        },
        {
          "id": "day2_header_row",
          "component": "Row",
          "children": [
            "day2_icon",
            "day2_title"
          ],
          "align": "center"
        },
        {
          "id": "day2_icon",
          "component": "Image",
          "url": "../assets/r_000264_01_1_calendar-event.svg",
          "variant": "icon"
        },
        {
          "id": "day2_title",
          "component": "Text",
          "text": "Day 2 - Bamboo Groves & Wild Monkeys",
          "variant": "h3"
        },
        {
          "id": "day2_subtitle",
          "component": "Text",
          "text": "Arashiyama District | Bamboo Grove & Monkey Park | Nature & Hiking",
          "variant": "h4"
        },
        {
          "id": "day2_desc",
          "component": "Text",
          "text": "Take the JR Sagano Line to Saga-Arashiyama Station (10-minute walk to main street). Visit the famous Bamboo Grove early to avoid crowds. Cross the Togetsukyo Bridge to access the Iwatayama Monkey Park; the entrance is near the bridge, and the 20-minute uphill hike is safe and rewarding for children, allowing them to feed monkeys from a protected hut. Lunch options in Arashiyama include udon and matcha soft-serve ice cream."
        },
        {
          "id": "day2_btn",
          "component": "Button",
          "child": "day2_btn_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "http://www.monkeypark.jp/"
              }
            }
          }
        },
        {
          "id": "day2_btn_text",
          "component": "Text",
          "text": "Monkey Park Info"
        },
        {
          "id": "day3_card",
          "component": "Card",
          "child": "day3_col"
        },
        {
          "id": "day3_col",
          "component": "Column",
          "children": [
            "day3_header_row",
            "day3_subtitle",
            "day3_desc",
            "day3_btn"
          ]
        },
        {
          "id": "day3_header_row",
          "component": "Row",
          "children": [
            "day3_icon",
            "day3_title"
          ],
          "align": "center"
        },
        {
          "id": "day3_icon",
          "component": "Image",
          "url": "../assets/r_000784_01_3_cart.svg",
          "variant": "icon"
        },
        {
          "id": "day3_title",
          "component": "Text",
          "text": "Day 3 - Golden Pavilion & The Kitchen of Kyoto",
          "variant": "h3"
        },
        {
          "id": "day3_subtitle",
          "component": "Text",
          "text": "North & Central Kyoto | Kinkaku-ji, Nijo Castle, Nishiki Market | Food & Culture",
          "variant": "h4"
        },
        {
          "id": "day3_desc",
          "component": "Text",
          "text": "Take a direct bus to Kinkaku-ji (Golden Pavilion); the walking path is short and visually striking. Transit to Nijo Castle (subway to Nijojo-mae); children often enjoy the \"nightingale floors\" that chirp to warn of intruders. Finish the afternoon at Nishiki Market (short walk from Shijo Station). Known as \"Kyoto's Kitchen,\" it offers skewers, tamagoyaki (egg omelet), and sweets perfect for snacking."
